<?php
declare(strict_types=1);
require __DIR__ . '/../backend/src/bootstrap.php';
$admin = require_admin();
$q = trim((string)($_GET['q'] ?? '')); $page = max(1,(int)($_GET['page'] ?? 1)); $perPage = 10;
$sort = (string)($_GET['sort'] ?? 'name'); $dir = strtolower((string)($_GET['direction'] ?? 'asc')) === 'desc' ? 'DESC' : 'ASC';
$sortColumns = ['name'=>'full_name','email'=>'email','role'=>'role','created'=>'created_at']; if (!isset($sortColumns[$sort])) $sort='name';
$where = ''; $params=[]; if ($q !== '') { $where = ' WHERE full_name LIKE :name OR email LIKE :email OR CAST(id AS CHAR)=:id'; $like='%'.$q.'%'; $params=['name'=>$like,'email'=>$like,'id'=>$q]; }
$count=db()->prepare('SELECT COUNT(*) FROM users'.$where); $count->execute($params); $total=(int)$count->fetchColumn();
$pages=max(1,(int)ceil($total/$perPage)); $page=min($page,$pages); $offset=($page-1)*$perPage;
$stmt=db()->prepare('SELECT id,full_name,email,role,is_active,created_at FROM users'.$where.' ORDER BY '.$sortColumns[$sort].' '.$dir.', id DESC LIMIT :limit OFFSET :offset');
foreach($params as $key=>$value) $stmt->bindValue(':'.$key,$value); $stmt->bindValue(':limit',$perPage,PDO::PARAM_INT); $stmt->bindValue(':offset',$offset,PDO::PARAM_INT); $stmt->execute(); $users=$stmt->fetchAll();
$flash=pull_flash(); $query=$_GET; unset($query['page']);
?>
<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Пользователи — FinanceAssistant</title><link rel="stylesheet" href="auth.css"></head><body><div class="dashboard"><aside class="sidebar"><div class="logo"><div class="logo-mark">₽</div>FinanceAssistant</div><nav><a href="dashboard.php">Личный кабинет</a><a href="admin-transactions.php">Все записи</a><a class="active" href="admin-users.php">Пользователи</a><a href="logout.php">Выйти</a></nav></aside><main class="main"><div class="topbar"><div><h1>Управление пользователями</h1><p>Всего аккаунтов: <?= $total ?> · текущий администратор: <?= e($admin['email']) ?></p></div><a class="action-link" href="admin-transactions.php">← К записям</a></div>
<?php if($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<form class="filters" method="get"><div class="field"><label for="q">Поиск по имени, email или ID</label><input id="q" name="q" value="<?= e($q) ?>" maxlength="100"></div><div class="filter-actions"><button class="btn" type="submit">Найти</button><a href="admin-users.php">Сбросить</a></div></form>
<section class="panel"><h2>Пользователи · страница <?= $page ?> из <?= $pages ?></h2><div class="table-wrap"><table><thead><tr><th>ID</th><th><a href="?<?= e(http_build_query(array_merge($query,['sort'=>'name','direction'=>$sort==='name'&&$dir==='ASC'?'desc':'asc']))) ?>">Имя ↕</a></th><th><a href="?<?= e(http_build_query(array_merge($query,['sort'=>'email','direction'=>$sort==='email'&&$dir==='ASC'?'desc':'asc']))) ?>">Email ↕</a></th><th><a href="?<?= e(http_build_query(array_merge($query,['sort'=>'role','direction'=>$sort==='role'&&$dir==='ASC'?'desc':'asc']))) ?>">Роль ↕</a></th><th>Состояние</th><th>Создан</th><th>Управление</th></tr></thead><tbody>
<?php foreach($users as $u): ?><tr><td><?= (int)$u['id'] ?></td><td><?= e($u['full_name']) ?></td><td><?= e($u['email']) ?></td><td><?= $u['role']==='admin'?'Администратор':'Пользователь' ?></td><td><?= $u['is_active']?'Активен':'Заблокирован' ?></td><td><?= e(date('d.m.Y',strtotime($u['created_at']))) ?></td><td><?php if((int)$u['id']===(int)$admin['id']): ?><small>Текущий аккаунт</small><?php else: ?><form method="post" action="admin-user-action.php" class="user-actions"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><select name="role"><option value="user" <?= $u['role']==='user'?'selected':'' ?>>Пользователь</option><option value="admin" <?= $u['role']==='admin'?'selected':'' ?>>Администратор</option></select><select name="is_active"><option value="1" <?= $u['is_active']?'selected':'' ?>>Активен</option><option value="0" <?= !$u['is_active']?'selected':'' ?>>Заблокирован</option></select><button type="submit">Сохранить</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$users): ?><tr><td class="empty" colspan="7">Пользователи не найдены.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a href="?<?= e(http_build_query(array_merge($query,['page'=>$page-1]))) ?>">← Назад</a><?php endif; ?><span>Страница <?= $page ?> из <?= $pages ?></span><?php if($page<$pages): ?><a href="?<?= e(http_build_query(array_merge($query,['page'=>$page+1]))) ?>">Далее →</a><?php endif; ?></div></section></main></div></body></html>
